from chainer import cuda
from chainer import function
from chainer.utils import type_check


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_types):
        type_check.expect(in_types.size() == 1)

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)

from chainer import function
from chainer import utils


class Copy(function.Function):

    """Copy an input variable onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_type):
        utils_type = utils.force_available_types(*in_type)
        if not all([t == types.Tuple[types.Indexable],
                    types.Tuple[]](
            types.Indexable(
                types.Float(memory_extent=types.External),
                types.Integer,
                is_contiguous=types.Optional[types.Bool]
            ),
            types.Tuple[]),
            types.Tuple[
                types.Indexable(
                    types.Float(),
                    types.Integer,
                    memory_extent=types.Internal,
                    is_contiguous=types.Bool)],
            types.Tuple[types.Float])) \
                in utils_type:
            raise types.TypeError(
                'Expected tuple of float or numpy.ndarray or '
                'numpy.ndarray copy, but got tuple of {}, {}'.format(
                    in_type[0], in_type[1]))

    def check_type_backward(self, in_types, output_arrays_types):
        if not all(output_arrays_types):
            raise types.TypeError(
                'Output must be numpy.ndarray, but got {}'.format(
                    output_arrays_types))

    def check_backward_data_type_consistency(self, in_data, grad_outputs):
        if in_data[0].dtype != grad_outputs[0].dtype:
            raise types.TypeError(
                'Data type of input and output of Copy are consistent.')

    def check_backward_evaluate(self, in_data, grad_outputs, output_data):
        if output_data is None:
            output_data = in_data[0].copy()
        if not (output_data == in_data[0]).all():
            raise types.TypeError(
                'Values of input and output of Copy are consistent.')

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)

from os import walk, sep, chdir, pardir, split, join, abspath
from glob import glob

# System path separator (usually slash or backslash)
sepd = {"sep": sep}

# Files having at least one of these in their path will be excluded
EXCLUDE = set([
    "%(sep)sthirdparty%(sep)s" % sepd,
    "%(sep)sprinting%(sep)spretty%(sep)s" % sepd,
])

def test_no_trailing_whitespace():
    message = "File contains trailing whitespace: %s, line %s."
    base_path = split(__file__)[0]
    base_path += sep + pardir + sep + pardir # go to sympy/
    base_path = abspath(base_path)
    for root, dirs, files in walk(base_path):
        for fname in glob(join(root, "*.py")):
            if filter(lambda ex: ex in fname, EXCLUDE):
                continue
            file = open(fname, "r")
            try:
                for idx, line in enumerate(file):
                    if line.rstrip('\n').endswith(" "):
                        assert False, message % (fname, idx+1)
            finally:
                file.close()

